class TestHost final:public CFrameWnd {void PostNcDestroy()override{}};
class ActivationBlock {HHOOK hook_;public:ActivationBlock(){hook_=SetWindowsHookEx(WH_CBT,[](int n,WPARAM w,LPARAM l)->LRESULT{return n==HCBT_ACTIVATE?1:CallNextHookEx(nullptr,n,w,l);},nullptr,GetCurrentThreadId());if(!hook_)throw std::runtime_error("Cannot isolate command tests");}~ActivationBlock(){UnhookWindowsHookEx(hook_);}};
sct::core::DocumentState Source(){using namespace sct::core;Image image;image.Create(320,220);auto state=Document(std::move(image)).State();for(int i=0;i<3;++i){Annotation a;a.tool=Tool::Step;a.rect={100-i*30,20+i*40,120-i*30,40+i*40};a.number=8+i;state.objects.push_back(a);}return state;}
void Core(Check check,const std::filesystem::path& dir){using namespace sct;CString error;services::EditorShortcuts entries{{L"sentinel",0,0}};
    for(auto input:{L"Ctrl+K",L"Alt+Shift+F12",L"Delete",L"Ctrl+PageDown",L"-"}){UINT mods=99,key=99;check(services::ParseEditorShortcut(input,mods,key),"supported editor shortcut parses");UINT m=99,k=99;check(services::ParseEditorShortcut(services::EditorShortcutText(mods,key),m,k)&&m==mods&&k==key,"shortcut text round trip retains exact modifiers/key");}
    for(auto input:{L"K",L"Ctrl+Ctrl+K",L"Ctrl+Tab",L"Alt+F4",L"Ctrl+Enter",L"Win+K",L"Ctrl+F13",L"Ctrl++K"}){UINT mods=99,key=99;check(!services::ParseEditorShortcut(input,mods,key)&&mods==99&&key==99,"reserved or malformed shortcut rejects without partial output");}
    check(services::EffectiveEditorShortcuts(L"Copy=-,RenumberSteps=Ctrl+C",entries,error),"explicitly disabling an old default allows intentional reassignment");
    const auto original=services::EncodeEditorShortcuts(entries);for(auto input:{L"RenumberSteps=Ctrl+C",L"Copy=Ctrl+K,Copy=Ctrl+J",L"Copy=Ctrl+K,PasteImage=Ctrl+K",L"Copy=Ctrl+K,",L"Copy=Ctrl+K\nFormat=png",L"Copy=Ctrl+K\r",L"Copy=Ctrl+K "})check(!services::EffectiveEditorShortcuts(input,entries,error)&&services::EncodeEditorShortcuts(entries)==original,"duplicate/default conflicts/injection reject transactionally");
    services::Settings settings;settings.editorShortcuts=L"Copy=-,RenumberSteps=Ctrl+C";services::ConfigService config((dir/L"editor-shortcuts.ini").c_str());services::Settings loaded;check(config.Save(settings,error)&&config.Load(loaded,error)&&loaded.editorShortcuts==settings.editorShortcuts,"private portable INI persists editor shortcuts without global registration");std::vector<BYTE> before,after;services::ReadBytes((dir/L"editor-shortcuts.ini").c_str(),before,error);settings.editorShortcuts=L"Copy=Ctrl+S";check(!config.Save(settings,error)&&services::ReadBytes((dir/L"editor-shortcuts.ini").c_str(),after,error)&&before==after,"conflicting shortcut save preserves existing INI bytes");
    const auto source=Source();bool changed=false;auto state=core::RenumberSteps(source,{},1,core::StepOrder::Creation,changed);check(changed&&state.objects[0].number==1&&state.objects[2].number==3&&state.base==source.base,"creation renumber changes numbers only and retains shared base");check(EqualRect(&state.objects[1].rect,&source.objects[1].rect)&&state.objects[1].color==source.objects[1].color,"renumber preserves geometry and drawing style");state=core::RenumberSteps(source,{},5,core::StepOrder::LeftToRight,changed);check(state.objects[2].number==5&&state.objects[0].number==7,"left-to-right numbering orders geometry deterministically");state=core::RenumberSteps(source,{1},20,core::StepOrder::TopToBottom,changed);check(state.objects[0].number==8&&state.objects[1].number==20&&state.objects[2].number==10,"selected-only renumber preserves unrelated steps");state=source;state.objects[1].hidden=true;state=core::RenumberSteps(state,{},1,core::StepOrder::Creation,changed);check(state.objects[0].number==1&&state.objects[1].number==9&&state.objects[2].number==2,"hidden steps are excluded without consuming a number");
    for(int kind=0;kind<4;++kind){auto bad=source;if(kind==0)bad.objects[1].locked=true;bool rejected=false;try{core::RenumberSteps(bad,{},kind==1?100000:kind==2?0:1,kind==3?static_cast<core::StepOrder>(8):core::StepOrder::Creation,changed);}catch(const std::exception&){rejected=true;}check(rejected&&bad.objects[0].number==8,"locked/overflow/invalid sequences reject without changing inputs");}
    state=core::RenumberSteps(source,{},99998,core::StepOrder::Creation,changed);std::vector<BYTE> bytes;core::DocumentState decoded;check(services::EncodeProject(state,bytes,error)&&services::DecodeProject(bytes,decoded,error)&&decoded.objects.back().number==100000,"highest valid number remains compatible with existing project schema");core::Document document;document.Reset(source);document.Commit(state);check(document.Undo()&&document.State().objects[0].number==8&&document.Redo()&&document.State().objects.back().number==100000,"batch numbering is one undo/redo step");
}
